import android.os.Bundle
import androidx.appcompat.app.AppCompatActivity
import com.mapbox.mapboxsdk.maps.MapView
import com.mapbox.mapboxsdk.maps.MapLibreMap
import com.mapbox.mapboxsdk.maps.Style
import com.mapbox.mapboxsdk.style.sources.RasterDemSource
import com.mapbox.mapboxsdk.style.layers.Terrain
import com.mapbox.mapboxsdk.geometry.LatLng
import com.mapbox.mapboxsdk.camera.CameraUpdateFactory

class MainActivity : AppCompatActivity() {

    private lateinit var mapView: MapView
    private var mapLibreMap: MapLibreMap? = null

    // ----  URL of the DEM source (same as the web example) ----
    private val DEM_SOURCE_ID = "dem"
    private val DEM_URL = "https://example.com/terrain.json"   // <-- change to your URL

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_main)

        mapView = findViewById(R.id.mapView)
        mapView.onCreate(savedInstanceState)

        // Load a style (you can use any style you like)
        mapView.getMapAsync { mapboxMap ->
            mapLibreMap = mapboxMap

            // Wait until the style is fully loaded before touching it
            mapboxMap.setStyle(Style.Builder().fromUri(Style.MAPBOX_STREETS)) { style ->

                // ----------------------------------------------------
                // 4️⃣  1️⃣ Add the raster‑DEM source
                // ----------------------------------------------------
                val demSource = RasterDemSource(
                    DEM_SOURCE_ID,
                    DEM_URL
                )
                style.addSource(demSource)

                // ----------------------------------------------------
                // 5️⃣  2️⃣ Enable terrain using that source
                // ----------------------------------------------------
                // `Terrain` is a *layer*‑like object that lives on the style.
                // The `exaggeration` parameter is a float (1.0 = real scale).
                val terrain = Terrain(DEM_SOURCE_ID).apply {
                    exaggeration(1.5f)          // same as web's `exaggeration: 1.5`
                }
                style.setTerrain(terrain)

                // ----------------------------------------------------
                // (Optional) Move the camera so you can see the 3‑D effect
                // ----------------------------------------------------
                val target = LatLng(45.0, -122.0)   // pick a location that has DEM data
                mapboxMap.animateCamera(
                    CameraUpdateFactory.newLatLngZoom(target, 12.0),
                    1500
                )
            }
        }
    }

    // ------------------------------------------------------------
    // 6️⃣  Forward lifecycle events to the MapView
    // ------------------------------------------------------------
    override fun onStart() = super.onStart().also { mapView.onStart() }
    override fun onResume() = super.onResume().also { mapView.onResume() }
    override fun onPause() = super.onPause().also { mapView.onPause() }
    override fun onStop() = super.onStop().also { mapView.onStop() }
    override fun onLowMemory() = super.onLowMemory().also { mapView.onLowMemory() }
    override fun onDestroy() = super.onDestroy().also { mapView.onDestroy() }
    override fun onSaveInstanceState(outState: Bundle) {
        super.onSaveInstanceState(outState)
        mapView.onSaveInstanceState(outState)
    }
}
```

