## 3. If you *don’t* want to use the package – DIY approach

### 3.1 Write a custom `URLProtocol`

```swift
final class PMTilesURLProtocol: URLProtocol {
    static var cache = NSCache<NSURL, NSData>()   // simple in‑memory cache

    override class func canInit(with request: URLRequest) -> Bool {
        return request.url?.scheme == "pmtiles"
    }

    override class func canonicalRequest(for request: URLRequest) -> URLRequest {
        return request
    }

    override func startLoading() {
        guard let url = request.url else { return }

        // 1️⃣  Strip the `pmtiles://` prefix → the real HTTP URL + tile coordinates
        //    Example: pmtiles://https://.../basemap.pmtiles/14/8623/5678
        //    → baseURL = https://.../basemap.pmtiles
        //    → z/x/y = 14/8623/5678
        let components = url.pathComponents.filter { $0 != "/" }
        guard components.count >= 3,
              let z = Int(components[components.count-3]),
              let x = Int(components[components.count-2]),
              let y = Int(components[components.count-1]) else {
            client?.urlProtocol(self, didFailWithError: NSError(domain: "PMTiles", code: -1, userInfo: nil))
            return
        }

        // 2️⃣  Build a tiny PMTiles reader (you can copy the Swift implementation from the package)
        //    The reader knows how to:
        //      * fetch the header (first ~200 bytes) via a range request
        //      * locate the tile entry in the index
        //      * issue a second range request for the tile data
        //    For brevity, the code is omitted – see `PMTilesArchive` in the package.

        PMTilesArchive.open(url: basePMTilesURL) { archive, error in
            guard let archive = archive, error == nil else {
                self.client?.urlProtocol(self, didFailWithError: error!)
                return
            }

            archive.tile(z: z, x: x, y: y) { data, error in
                if let data = data {
                    let response = URLResponse(url: url,
                                               mimeType: "application/octet-stream",
                                               expectedContentLength: data.count,
                                               textEncodingName: nil)
                    self.client?.urlProtocol(self, didReceive: response, cacheStoragePolicy: .notAllowed)
                    self.client?.urlProtocol(self, didLoad: data)
                    self.client?.urlProtocolDidFinishLoading(self)
                } else {
                    self.client?.urlProtocol(self, didFailWithError: error!)
                }
            }
        }
    }

    override func stopLoading() { /* cancel any pending network tasks */ }
}
```

Then register it once:

```swift
URLProtocol.registerClass(PMTilesURLProtocol.self)
```

