## 2️⃣ Tile‑cache helper (TypeScript)

```ts
// src/TileCache.ts
import { openDB, DBSchema, IDBPDatabase } from 'idb';

/**
 * IndexedDB schema for the tile cache.
 */
interface TileCacheDB extends DBSchema {
  /** Object store where each key is "z/x/y" and the value is a Blob (the .pbf) */
  tiles: {
    key: string;          // e.g. "12/3456/7890"
    value: Blob;          // the raw vector‑tile data
  };
}

/**
 * Tiny wrapper around IndexedDB that knows how to get / put tiles.
 */
export class TileCache {
  private static _instance: TileCache | null = null;
  private db!: IDBPDatabase<TileCacheDB>;

  private constructor() {}

  /** Singleton – you only need one cache per page */
  static async getInstance(): Promise<TileCache> {
    if (!TileCache._instance) {
      const cache = new TileCache();
      await cache._open();
      TileCache._instance = cache;
    }
    return TileCache._instance;
  }

  /** Open (or create) the IndexedDB database */
  private async _open() {
    this.db = await openDB<TileCacheDB>('tile-cache', 1, {
      upgrade(db) {
        // Create the object store if it does not exist yet.
        if (!db.objectStoreNames.contains('tiles')) {
          db.createObjectStore('tiles');
        }
      },
    });
  }

  /** Build the key used in the object store: "z/x/y" */
  private _makeKey(z: number, x: number, y: number): string {
    return `${z}/${x}/${y}`;
  }

  /** Retrieve a tile from the cache – returns `null` if not present */
  async getTile(z: number, x: number, y: number): Promise<Blob | null> {
    const key = this._makeKey(z, x, y);
    return (await this.db.get('tiles', key)) ?? null;
  }

  /** Store a tile in the cache (overwrites any existing entry) */
  async putTile(z: number, x: number, y: number, data: Blob): Promise<void> {
    const key = this._makeKey(z, x, y);
    await this.db.put('tiles', data, key);
  }
}
```

---

## 3️⃣ Register the `cache://` protocol with MapLibre GL JS

```ts
// src/registerCacheProtocol.ts
import maplibregl from 'maplibre-gl';
import { TileCache } from './TileCache';

/**
 * Register a custom protocol named "cache".
 *
 * The handler receives:
 *   - params: { url: string, request: Request, ... }
 *   - abort: AbortSignal (optional, you can respect it for network fetches)
 *
 * It must return a Promise that resolves to:
 *   - Response | ArrayBuffer | string | null
 *
 * In our case we return a Response built from the cached Blob (or from the network).
 */
export async function registerCacheProtocol(): Promise<void> {
  // The protocol name is the part before the colon, i.e. "cache"
  maplibregl.addProtocol('cache', async (params, abort) => {
    // --------------------------------------------------------------
    // 1️⃣ Parse the URL: cache://tiles/{z}/{x}/{y}.pbf
    // --------------------------------------------------------------
    // `params.url` is the full URL string, e.g. "cache://tiles/12/3456/7890.pbf"
    const url = new URL(params.url);
    // Remove the leading slash from pathname and split
    const [, zStr, xStr, yWithExt] = url.pathname.split('/');
    const z = Number(zStr);
    const x = Number(xStr);
    // y may have an extension (".pbf") – strip it
    const y = Number(yWithExt.split('.')[0]);

    if (Number.isNaN(z) || Number.isNaN(x) || Number.isNaN(y)) {
      console.warn('Cache protocol: malformed tile coordinates', params.url);
      return null; // Let MapLibre try the next source (or fail)
    }

    // --------------------------------------------------------------
    // 2️⃣ Try to read from IndexedDB
    // --------------------------------------------------------------
    const cache = await TileCache.getInstance();
    const cachedBlob = await cache.getTile(z, x, y);

    if (cachedBlob) {
      // We have it locally – return a Response that MapLibre can read.
      return new Response(cachedBlob, {
        status: 200,
        headers: { 'Content-Type': 'application/x-protobuf' },
      });
    }

    // --------------------------------------------------------------
    // 3️⃣ Not in cache → fetch from the network, store, then return.
    // --------------------------------------------------------------
    // Build the *real* HTTP URL you want to use as the source.
    // For this demo we assume the original tiles live at:
    //   https://example.com/tiles/{z}/{x}/{y}.pbf
    const networkUrl = `https://example.com/tiles/${z}/${x}/${y}.pbf`;

    try {
      const response = await fetch(networkUrl, { signal: abort });

      if (!response.ok) {
        console.warn(`Cache protocol: network request failed ${response.status}`);
        return response; // Propagate the error to the map (it will show a missing tile)
      }

      // Clone the response because we need one copy for the cache and one for the map.
      const responseClone = response.clone();

      // Store the raw bytes in IndexedDB (as a Blob)
      const blob = await responseClone.blob();
      await cache.putTile(z, x, y, blob);

      // Return the original response (still readable by MapLibre)
      return response;
    } catch (err) {
      if ((err as any).name === 'AbortError') {
        // The map cancelled the request (e.g. tile moved out of view)
        return null;
      }
      console.error('Cache protocol: fetch error', err);
      return null;
    }
  });
}
```

> **Important notes**
> - The handler **must** return a `Response` (or `ArrayBuffer`/`string`). Returning a `Blob` directly is not supported by MapLibre.
> - Respect the `abort` signal – we forward it to `fetch`. If the request is aborted we simply return `null`.
> - The protocol name (`cache`) is the part before the colon in the URL (`cache://…`). You can pick any name you like, just keep it consistent with the style JSON.

