## 4️⃣ Put it all together – create the map

```ts
// src/main.ts
import maplibregl from 'maplibre-gl';
import 'maplibre-gl/dist/maplibre-gl.css';
import { registerCacheProtocol } from './registerCacheProtocol';

// 1️⃣ Register the protocol *before* you instantiate the map
registerCacheProtocol()
  .then(() => {
    // 2️⃣ Create the map
    const map = new maplibregl.Map({
      container: 'map', // <div id="map"></div> in your HTML
      style: {
        version: 8,
        sources: {
          // The source uses the custom scheme
          myVectorTiles: {
            type: 'vector',
            // Note the .pbf extension – MapLibre expects it for vector tiles
            url: 'cache://tiles/{z}/{x}/{y}.pbf',
            // Optional: set a maxzoom that matches your source
            maxzoom: 14,
          },
        },
        layers: [
          {
            id: 'my-layer',
            type: 'fill',
            source: 'myVectorTiles',
            'source-layer': 'my_layer_name', // whatever the source layer is called
            paint: {
              'fill-color': '#88c0d0',
              'fill-opacity': 0.6,
            },
          },
        ],
      },
      center: [0, 0],
      zoom: 2,
    });

    // Optional: expose for debugging
    (window as any).map = map;
  })
  .catch((e) => {
    console.error('Failed to register cache protocol', e);
  });
```

